91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper,
95	                                 OwnerTelephoneUniquenessValidator telephoneUniquenessValidator,
96	                                 OwnerHouseholdUniquenessValidator householdUniquenessValidator,
97	                                 OwnerHouseholdRegistrar householdRegistrar,
98	                                 NamesakeCounter namesakeCounter,
99	                                 CityOwnerCounter cityOwnerCounter,
100	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
101	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneUniquenessValidator = telephoneUniquenessValidator;
107	        this.householdUniquenessValidator = householdUniquenessValidator;
108	        this.householdRegistrar = householdRegistrar;
109	        this.namesakeCounter = namesakeCounter;
110	        this.cityOwnerCounter = cityOwnerCounter;
111	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
112	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
113	    }
