140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
144	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
148	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
149	        this.dailyRegistrationCapacityValidator.validateHasCapacity();
150	        this.telephoneUniquenessValidator.validateUnique(owner.getTelephone());
151	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
152	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
153	            this.householdUniquenessValidator.validateUnique(owner.getLastName(), owner.getAddress());
154	        } else {
155	            this.householdRegistrar.assignHousehold(owner);
156	        }
157	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
158	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
159	            this.cityOwnerCounter.count(owner.getCity())));
160	        this.clinicService.saveOwner(owner);
161	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
