199	        Owner owner = this.clinicService.findOwnerById(ownerId);
200	        if (owner == null) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        HttpHeaders headers = new HttpHeaders();
204	        Pet pet = petMapper.toPet(petFieldsDto);
205	        owner.setId(ownerId);
206	        pet.setOwner(owner);
207	        pet.getType().setName(null);
208	        this.clinicService.savePet(pet);
209	        PetDto petDto = petMapper.toPetDto(pet);
210	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
211	            .buildAndExpand(pet.getId()).toUri());
212	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
218	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
219	        if (currentOwner != null) {
220	            Pet currentPet = this.clinicService.findPetById(petId);
221	            if (currentPet != null) {
222	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
223	                currentPet.setName(petFieldsDto.getName());
224	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
225	                this.clinicService.savePet(currentPet);
226	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
