242	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
243	            .buildAndExpand(visit.getId()).toUri());
244	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
245	    }
